attrs.body:
for a0 in 0..8:
    for a1 in 0..128:
        for a2 in 0..512:
            for a3 in 0..1024:
                in0 = load x0[0, a2, a3]
                in1 = load x1[a0, a3, a1]
                f32 v0 = multiply(in0, in1)
                acc0 <- add(acc0, v0) over a3
            transpose[a0, a1, a2] = acc0
